#!/usr/bin/env node
// Usage: node apps/api/scripts/embed-plan.mjs
// Regenerates src/verification/locator/plan-image.ts from assets/plano.webp (the floor plan the
// seat locator shows the model). Workers have no filesystem, so the image ships as a base64 module.
import { readFileSync, writeFileSync } from "node:fs";

const asset = new URL("../assets/plano.webp", import.meta.url);
const target = new URL("../src/verification/locator/plan-image.ts", import.meta.url);

const base64 = readFileSync(asset).toString("base64");
const out = [
  "// Generated by scripts/embed-plan.mjs from assets/plano.webp - do not edit.",
  `export const PLAN_MIME = "image/webp";`,
  `export const PLAN_WEBP_BASE64 =`,
  `  "${base64}";`,
  "",
].join("\n");
writeFileSync(target, out);
console.log(`wrote src/verification/locator/plan-image.ts (${base64.length} base64 chars)`);
